{
  "schemaVersion": "ride-output-v2.2.0",
  "label": {
    "text": "总距离 31.1 公里的骑行，移动时长 1 小时 2 分钟",
    "conclusionType": "fact",
    "claimIds": [
      "claim:demo-ride-2026-08-20:v2:metric.distanceM",
      "claim:demo-ride-2026-08-20:v2:timing.movingDurationS"
    ]
  },
  "overallAssessment": {
    "text": "本次可用数据有限，但基于现有数据，这是一次以平路为主的骑行，整体速度较高，心率负荷偏大，踏频处于中等水平。",
    "conclusionType": "fact",
    "claimIds": [
      "claim:demo-ride-2026-08-20:v2:terrain.trendFlatDistanceM",
      "claim:demo-ride-2026-08-20:v2:speed.mean",
      "claim:demo-ride-2026-08-20:v2:heart_rate.mean",
      "claim:demo-ride-2026-08-20:v2:cadence.mean"
    ]
  },
  "highlights": [
    {
      "text": "全程平均速度 28.47 km/h，整体速度较快。",
      "conclusionType": "fact",
      "claimIds": [
        "claim:demo-ride-2026-08-20:v2:speed.mean"
      ]
    },
    {
      "text": "平路里程约 29 公里，占绝大部分，骑行以平路为主。",
      "conclusionType": "fact",
      "claimIds": [
        "claim:demo-ride-2026-08-20:v2:terrain.trendFlatDistanceM"
      ]
    }
  ],
  "dimensions": [
    {
      "dimensionId": "pacingExecution",
      "assertions": [
        {
          "text": "本次骑行总距离 31.1 公里，移动时长 1 小时 2 分钟，总用时 1 小时 6 分钟，途中停车 1 次。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:metric.distanceM",
            "claim:demo-ride-2026-08-20:v2:timing.movingDurationS",
            "claim:demo-ride-2026-08-20:v2:metric.elapsedDurationS",
            "claim:demo-ride-2026-08-20:v2:stops.count"
          ]
        },
        {
          "text": "全程平均速度 28.47 km/h，速度数据部分缺失，但整体速度水平较高。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:speed.mean"
          ]
        },
        {
          "text": "巡航段中，第一段平均速度 29.97 km/h，第二段 27.96 km/h，第三段 29.23 km/h，速度略有波动。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:segment.cruise.cruise-0-637.speed.mean",
            "claim:demo-ride-2026-08-20:v2:segment.cruise.cruise-1-2102.speed.mean",
            "claim:demo-ride-2026-08-20:v2:segment.cruise.cruise-2-2334.speed.mean"
          ]
        },
        {
          "text": "地形以平路为主，平路里程约 29 公里，下坡约 1.6 公里，爬坡约 0 公里。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:terrain.trendFlatDistanceM",
            "claim:demo-ride-2026-08-20:v2:terrain.trendDescentDistanceM",
            "claim:demo-ride-2026-08-20:v2:terrain.trendClimbDistanceM"
          ]
        },
        {
          "text": "平路段中，第一段平均速度 28.37 km/h，第二段 29.29 km/h，速度整体较高。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:segment.terrain.terrain-flat-2022.7-6845.7.speed.mean",
            "claim:demo-ride-2026-08-20:v2:segment.terrain.terrain-flat-6846.2-31056.1.speed.mean"
          ]
        },
        {
          "text": "下坡段平均速度 20.25 km/h，速度相对较低。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:segment.terrain.terrain-descent-412.8-2022.7.speed.mean"
          ]
        },
        {
          "text": "整体配速较高，但速度数据部分缺失，无法全面评估速度稳定性。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:speed.mean"
          ]
        }
      ]
    },
    {
      "dimensionId": "heartRateLoad",
      "assertions": [
        {
          "text": "全程平均心率 168 bpm，心率数据部分缺失，整体心率水平较高。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:heart_rate.mean"
          ]
        },
        {
          "text": "心率区间分布中，Z4 区间占比 58%，Z5 区间占比 21%，高强度区间（Z5-Z7）合计占比 78%，整体负荷偏大。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:heartRate.zone.z4",
            "claim:demo-ride-2026-08-20:v2:heartRate.zone.z5",
            "claim:demo-ride-2026-08-20:v2:heartRate.zone.highIntensityCombined"
          ]
        },
        {
          "text": "巡航段中，第一段平均心率 159 bpm，第二段 174 bpm，第三段 175 bpm，心率逐渐升高。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:segment.cruise.cruise-0-637.heart_rate.mean",
            "claim:demo-ride-2026-08-20:v2:segment.cruise.cruise-1-2102.heart_rate.mean",
            "claim:demo-ride-2026-08-20:v2:segment.cruise.cruise-2-2334.heart_rate.mean"
          ]
        },
        {
          "text": "平路段中，第一段平均心率 159 bpm，第二段 174 bpm，心率同样呈上升趋势。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:segment.terrain.terrain-flat-2022.7-6845.7.heart_rate.mean",
            "claim:demo-ride-2026-08-20:v2:segment.terrain.terrain-flat-6846.2-31056.1.heart_rate.mean"
          ]
        },
        {
          "text": "下坡段平均心率 127 bpm，相对较低。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:segment.terrain.terrain-descent-412.8-2022.7.heart_rate.mean"
          ]
        },
        {
          "text": "本次骑行心率负荷较大，高强度区间占比高，整体属于高强度骑行。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:heartRate.zone.highIntensityCombined"
          ]
        }
      ]
    },
    {
      "dimensionId": "cadenceStrategy",
      "assertions": [
        {
          "text": "全程平均踏频 79 rpm，踏频数据部分缺失，整体处于中等水平。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:cadence.mean"
          ]
        },
        {
          "text": "踏频区间分布中，耐力区间占比 48%，高踏频区间占比 33%，整体以耐力区间为主。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:cadence.zone.endurance",
            "claim:demo-ride-2026-08-20:v2:cadence.zone.high"
          ]
        },
        {
          "text": "巡航段中，第一段平均踏频 82 rpm，第二段 88 rpm，第三段 87 rpm，踏频整体较高。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:segment.cruise.cruise-0-637.cadence.mean",
            "claim:demo-ride-2026-08-20:v2:segment.cruise.cruise-1-2102.cadence.mean",
            "claim:demo-ride-2026-08-20:v2:segment.cruise.cruise-2-2334.cadence.mean"
          ]
        },
        {
          "text": "平路段中，第一段平均踏频 74 rpm，第二段 83 rpm，踏频逐渐升高。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:segment.terrain.terrain-flat-2022.7-6845.7.cadence.mean",
            "claim:demo-ride-2026-08-20:v2:segment.terrain.terrain-flat-6846.2-31056.1.cadence.mean"
          ]
        },
        {
          "text": "下坡段平均踏频 49 rpm，明显较低。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:segment.terrain.terrain-descent-412.8-2022.7.cadence.mean"
          ]
        },
        {
          "text": "踏频整体处于中等水平，但部分数据缺失，无法全面评估踏频稳定性。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:cadence.mean"
          ]
        }
      ]
    },
    {
      "dimensionId": "crossSensorCoordination",
      "assertions": [
        {
          "text": "速度与心率在同一时间窗口内的共同覆盖率为 100%，说明两者数据同步性良好。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:relation.fixed.speed-heart_rate.aggregate"
          ]
        },
        {
          "text": "代表性窗口中，速度与心率共同覆盖率分别为 70%、100%、100%，整体同步性较高。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:relation.fixed.speed-heart_rate.rep.1",
            "claim:demo-ride-2026-08-20:v2:relation.fixed.speed-heart_rate.rep.2",
            "claim:demo-ride-2026-08-20:v2:relation.fixed.speed-heart_rate.rep.3"
          ]
        },
        {
          "text": "速度与心率数据在时间上高度同步，为后续分析提供了可靠基础。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:demo-ride-2026-08-20:v2:relation.fixed.speed-heart_rate.aggregate"
          ]
        }
      ]
    }
  ],
  "suggestions": [
    {
      "text": "下次骑行可尝试在平路段保持更均匀的踏频，例如维持在 80-90 rpm 区间，以减少心率波动。",
      "conclusionType": "suggestion",
      "claimIds": [
        "claim:demo-ride-2026-08-20:v2:cadence.mean"
      ],
      "riskNote": "踏频调整需结合个人感受，避免过度改变导致不适。"
    },
    {
      "text": "鉴于本次高强度心率区间占比较高，建议后续安排低强度恢复骑行，以促进恢复。",
      "conclusionType": "suggestion",
      "claimIds": [
        "claim:demo-ride-2026-08-20:v2:heartRate.zone.highIntensityCombined"
      ],
      "riskNote": "恢复建议基于本次负荷，具体恢复计划需结合个人状态。"
    }
  ],
  "limitations": [
    "speedStability:CONTINUITY_GAP",
    "relation.fixed.speed-heart_rate.aggregate:AGGREGATED_FROM_123_WINDOWS",
    "power:SERIES_MISSING"
  ]
}
